parameters.jsCode:
// Parse Marcus's AI output to extract image direction and build Pollinations URL
const items = $input.all();
const item = items[0];
const output = item.json.output || '';
const config = $('Config — Brand + Brief').first().json;

// Extract the IMAGE DIRECTION section from Marcus's output
let imagePrompt = 'Professional minimalist social media graphic, bold typography, blue gradient background, clean modern design';

// Try to find IMAGE DIRECTION section
const imageMatch = output.match(/(?:IMAGE DIRECTION|VISUAL DIRECTION|Image Direction)[:\s]*([\s\S]*?)(?=\n\n## |\n\n------|$)/i);
if (imageMatch && imageMatch[1]) {
  imagePrompt = imageMatch[1]
    .replace(/^[#*\s]+/gm, '')
    .replace(/\n+/g, ', ')
    .replace(/\*\*/g, '')
    .trim()
    .substring(0, 450);
}

// Add brand visual cues to the prompt
imagePrompt += ', electric blue #2D5BFF and deep navy #1A1A2E color scheme, clean minimal design, professional, high quality';

// Set dimensions based on platform
const dims = {
  'LinkedIn': { w: 1200, h: 627 },
  'X': { w: 1200, h: 675 },
  'Instagram': { w: 1080, h: 1080 }
};
const { w, h } = dims[config.platform] || dims['LinkedIn'];

// Build Pollinations.ai URL (completely free, no API key needed)
const encodedPrompt = encodeURIComponent(imagePrompt);
const imageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=${w}&height=${h}&nologo=true&seed=${Date.now()}`;

return [{
  json: {
    output: output,
    image_url: imageUrl,
    image_prompt: imagePrompt.substring(0, 200) + '...',
    image_width: w,
    image_height: h,
    platform: config.platform
  }
}];

