const sofiaOutput = $input.first().json.output || '';
const config = $('Config — Brand + Brief').item.json;

const escape = (str) => {
  if (!str) return '';
  return String(str).replace(/[_*[\]()~`>#+=|{}.!-]/g, '\\$&');
};

const formatAngles = (text) => {
  return text
    .replace(/##\s*/g, '\n*')
    .replace(/\n\n/g, '\n')
    + '*';
};

return [{
  json: {
    cleanOutput: escape(sofiaOutput),
    client: escape(config.client || 'N/A'),
    platform: escape(config.platform || 'N/A'),
    content_type: escape(config.content_type || 'N/A'),
    topic_hint: escape(config.topic_hint || 'N/A')
  }
}];

